def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid[:]]

    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    # Find the full-length separator.
    sep = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != background:
            sep = ("v", c, grid[0][c])
            break
    if sep is None:
        for r in range(h):
            if all(x == grid[r][0] for x in grid[r]) and grid[r][0] != background:
                sep = ("h", r, grid[r][0])
                break
    if sep is None:
        return out

    axis, pos, line_color = sep
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (background, line_color)]
    if not cells:
        return out

    if axis == "v":
        obj_cols = [c for r, c in cells]
        if max(obj_cols) < pos:
            target = min(obj_cols) - 1
        elif min(obj_cols) > pos:
            target = max(obj_cols) + 1
        else:
            return out
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    else:
        obj_rows = [r for r, c in cells]
        if max(obj_rows) < pos:
            target = min(obj_rows) - 1
        elif min(obj_rows) > pos:
            target = max(obj_rows) + 1
        else:
            return out
        if 0 <= target < h:
            for c in range(w):
                out[target][c] = 8

    return out
